import test from "node:test";
import assert from "node:assert/strict";
import { createWarehouseState } from "../src/domain/warehouse.mjs";
import { InMemoryWarehouseRepository } from "../src/infrastructure/in-memory-repository.mjs";
import { WarehouseService } from "../src/application/warehouse-service.mjs";
import { createWarehouseApi } from "../src/api/warehouse-api.mjs";
import { buildDashboardModel } from "../src/ui/dashboard-view.mjs";

function fixture() {
  const repository = new InMemoryWarehouseRepository(createWarehouseState({ A: 8, B: 3 }));
  const service = new WarehouseService(repository);
  return { repository, service, api: createWarehouseApi(service) };
}

test("allocates an order through the API and updates the dashboard", () => {
  const { api } = fixture();
  const result = api.allocateOrder({ orderId: "O-1", lines: [{ skuId: "A", quantity: 2 }] });
  assert.equal(result.ok, true);
  assert.equal(api.getSnapshot().stockBySku.A, 6);
  assert.deepEqual(buildDashboardModel(api.getSnapshot()), {
    skuCount: 2,
    availableUnits: 9,
    allocatedOrders: 1,
    recentEvents: [{ type: "order-allocated", orderId: "O-1" }]
  });
});

test("rejects allocation when stock is insufficient without mutating state", () => {
  const { api } = fixture();
  const result = api.allocateOrder({ orderId: "O-2", lines: [{ skuId: "B", quantity: 5 }] });
  assert.equal(result.ok, false);
  assert.deepEqual(result.shortages, [{ skuId: "B", quantity: 5, missing: 2 }]);
  assert.equal(api.getSnapshot().stockBySku.B, 3);
});

test("restocks an existing SKU", () => {
  const { api } = fixture();
  assert.deepEqual(api.restock({ skuId: "B", quantity: 4 }), { quantity: 7 });
  assert.equal(api.getSnapshot().events.at(-1).type, "stock-restocked");
});

